  s_qs_correct: ['Correct a measurement', 'एक नाप सुधारें', 'एक मोजमाप दुरुस्त करा'],
  qs_correct_d: ['The first record stays. This becomes version 2 with your reason, and everyone sees both.', 'पहला रिकॉर्ड रहता है। यह आपके कारण के साथ संस्करण 2 बनता है, और सब दोनों देखते हैं।', 'पहिली नोंद तशीच राहते. ही तुमच्या कारणासह आवृत्ती 2 होते, आणि सर्वांना दोन्ही दिसतात.'],
  qs_version: ['Version {n}', 'संस्करण {n}', 'आवृत्ती {n}'],
  cfg_acceptMins: ['Minutes a technician has to accept a breakdown before the office is told', 'ब्रेकडाउन मानने के लिए तकनीशियन के मिनट, फिर ऑफिस को सूचना', 'ब्रेकडाउन स्वीकारण्यासाठी तंत्रज्ञाला मिनिटे, नंतर ऑफिसला कळवले जाते'],
  err_test_vals: ['Enter the test values: levelling (mm), load tested (kg), ARD battery (V, 0 if none).', 'टेस्ट मान लिखें: लेवलिंग (mm), लोड टेस्ट (kg), ARD बैटरी (V, न हो तो 0)।', 'चाचणी मूल्ये लिहा: लेव्हलिंग (mm), लोड चाचणी (kg), ARD बॅटरी (V, नसल्यास 0).'],
  s_qcf_vals: ['Test values as numbers', 'टेस्ट मान अंकों में', 'चाचणी मूल्ये आकड्यांत'],
  qcf_vals_d: ['Write what you measured, not just a tick. These go in the lift record and the handover papers.', 'जो नापा वह लिखें, सिर्फ़ टिक नहीं। ये लिफ्ट रिकॉर्ड और हैंडओवर कागज़ों में जाते हैं।', 'जे मोजले ते लिहा, फक्त टिक नाही. हे लिफ्ट नोंद आणि हँडओव्हर कागदपत्रांत जातात.'],
  tv_level: ['Levelling error (mm)', 'लेवलिंग अंतर (mm)', 'लेव्हलिंग फरक (mm)'],
