  amc_good: ['Good', 'ठीक', 'चांगले'],
  amc_fair: ['Wearing', 'घिस रहा', 'झिजत आहे'],
  amc_replace: ['Replace', 'बदलें', 'बदला'],
  amc_fair_d: ['"Wearing" means it works today but will need a part soon. The office sees it in the lift record.', '"घिस रहा" मतलब आज चलता है पर जल्द पुर्ज़ा चाहिए। ऑफिस इसे लिफ्ट रिकॉर्ड में देखता है।', '"झिजत आहे" म्हणजे आज चालते पण लवकरच भाग लागेल. ऑफिसला हे लिफ्ट नोंदीत दिसते.'],
  err_cause: ['Choose what caused the breakdown.', 'ब्रेकडाउन का कारण चुनें।', 'ब्रेकडाउनचे कारण निवडा.'],
