  tr_customer_q1_c: ['Start work without talking', 'बिना बात किए काम शुरू करें', 'न बोलता काम सुरू करा'],
  tr_customer_q2: ['The customer wants to give you cash. What do you do?', 'ग्राहक आपको नकद देना चाहता है। आप क्या करेंगे?', 'ग्राहक तुम्हाला रोख देऊ इच्छितो. तुम्ही काय कराल?'],
  tr_customer_q2_a: ['Take it and give a receipt later', 'ले लें और रसीद बाद में दें', 'घ्या आणि पावती नंतर द्या'],
  tr_customer_q2_b: ['Take half of it', 'आधा ले लें', 'अर्धे घ्या'],
  tr_customer_q2_c: ['Ask them to pay the company bank account', 'उन्हें कंपनी के बैंक खाते में भुगतान करने को कहें', 'त्यांना कंपनीच्या बँक खात्यात पैसे भरायला सांगा'],
  tr_customer_q3: ['The customer is unhappy. What do you do?', 'ग्राहक नाखुश है। आप क्या करेंगे?', 'ग्राहक नाराज आहे. तुम्ही काय कराल?'],
  tr_customer_q3_a: ['Listen, make a ticket, say who will call back', 'सुनें, टिकट बनाएँ, बताएँ कौन कॉल करेगा', 'ऐका, तिकीट बनवा, कोण फोन करेल ते सांगा'],
